using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public sealed class CombatOperatorAutomationTests {
 static BasicCombatSimulation Fresh(bool general=true){var p=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/unity-project/QA/Unity1Artifacts/Fixtures/ce03-frontline-policy-UtU7yJ/prepared.json"));var s=BasicCombatSimulation.FromPreparedProfileForLocalTest(p,(JObject)p["ownedSelection"],(string)p["ownedSelection"]["accountId"],1);var configure=typeof(BasicCombatSimulation).GetMethod("ConfigureLocalOperatorAutomation");Assert.NotNull(configure,"New explicit policy must exist");configure.Invoke(s,new object[]{general});return s;}
 static void Auto(BasicCombatSimulation s,bool value)=>typeof(BasicCombatSimulation).GetMethod("SetUltimateAuto").Invoke(s,new object[]{value});
 static JObject Quiet(bool general=true){var j=JObject.Parse(Fresh(general).CaptureLocalState());foreach(var a in (JArray)j["actors"])a["ready"]=100000;return j;}
 static BasicCombatSimulation Restore(JObject j,bool general=true)=>BasicCombatSimulation.RestoreLocalState(j.ToString(),()=>Fresh(general));
 [Test] public void ExactServerV3PreparedUsesNewPolicyAndRejectsMutation(){var p=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/unity-project/QA/Unity1Artifacts/Fixtures/ce03-general-active-auto-hM29XX/prepared.json"));var c=new Ce03CommandContract((JObject)p["commandContract"]);var s=c.CreateLocalTest(p,(string)p["ownedSelection"]["accountId"],c.Revision,1);Assert.IsTrue((bool)s.ReadHudState()["generalAuto"]);Assert.AreEqual("ce03-headless-operator-auto-state-v1",(string)JObject.Parse(s.CaptureLocalState())["schema"]);p["commandContract"]["ultimates"]["perHit"]=5;Assert.Throws<FormatException>(()=>new Ce03CommandContract((JObject)p["commandContract"]));}
 [Test] public void NewPolicyHasFiveZeroChargesAndDefaultsManual(){var s=Fresh();var h=s.ReadHudState();Assert.AreEqual(5,((JArray)h["ultimates"]).Count);Assert.IsFalse((bool)h["ultimateAuto"]);Assert.IsTrue(((JArray)h["ultimates"]).All(x=>(int)x["charge"]==0));Assert.IsTrue((bool)h["generalAuto"]);Assert.AreEqual(s.CaptureLocalState(),BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),()=>Fresh()).CaptureLocalState());}
 [Test] public void GeneralSkillsAutomaticallyCastWithoutUltimateAuto(){var j=Quiet();foreach(var r in (JArray)j["skillReady"])r["ready"]=0;var s=Restore(j);s.Advance(500000,1);var commands=(JArray)JObject.Parse(s.CaptureLocalState())["commands"];Assert.AreEqual(3,commands.Count,"Enemy-target skills wait until entrance without rejection spam");s.Advance(5500000,11);commands=(JArray)JObject.Parse(s.CaptureLocalState())["commands"];Assert.AreEqual(5,commands.Count);Assert.IsTrue(commands.All(c=>((string)c["skill"]).EndsWith(".active")&&new[]{"CASTING","APPLIED"}.Contains((string)c["status"])));}
 [Test] public void ManualUltimateWinsOverBothAutomaticQueues(){var j=Quiet();foreach(var r in (JArray)j["skillReady"])r["ready"]=0;j["operatorAutomation"]["charge"]["op_kyle"]=100;var s=Restore(j);Auto(s,true);Assert.AreEqual("QUEUED",s.RequestSkill("manual-kyle","op_kyle","op_kyle.ultimate"));s.Advance(500000,1);var rows=(JArray)JObject.Parse(s.CaptureLocalState())["commands"];Assert.AreEqual(1,rows.Count(c=>((string)c["skill"]).StartsWith("op_kyle/")));Assert.AreEqual("CASTING",s.CommandStatus("manual-kyle"));Assert.AreEqual(0,(int)JObject.Parse(s.CaptureLocalState())["operatorAutomation"]["charge"]["op_kyle"]);}
 [Test] public void PauseAndRestorePreserveToggleAndDoNotSchedule(){var s=Fresh();Auto(s,true);s.SetPaused(true);var before=s.CaptureLocalState();s.Advance(5000000,10);Assert.AreEqual(before,s.CaptureLocalState());var restored=BasicCombatSimulation.RestoreLocalState(before,()=>Fresh());Assert.IsTrue((bool)restored.ReadHudState()["ultimateAuto"]);Assert.AreEqual(before,restored.CaptureLocalState());}
 [Test] public void GeneralAutoAndUltimateOnlySchemasCannotBeMixed(){var s=Fresh();Assert.Throws<ArgumentException>(()=>BasicCombatSimulation.RestoreLocalState(s.CaptureLocalState(),()=>Fresh(false)));}
 [Test] public void InvalidChargeAndMissingActorFailClosed(){var j=Quiet();j["operatorAutomation"]["charge"]["op_kyle"]=101;Assert.Throws<ArgumentException>(()=>Restore(j));j=Quiet();((JObject)j["operatorAutomation"]["charge"]).Remove("op_mira");Assert.Throws<ArgumentException>(()=>Restore(j));}
 [Test] public void OwnBasicHitOnlyChargesItsSource(){var s=Fresh(false);s.Advance(15000000,30);var hud=s.ReadHudState();foreach(var row in (JArray)hud["ultimates"]){string id=(string)row["actor"];Assert.Greater((int)row["hp"],0,"Fixture retains living sources");int hits=((JArray)hud["hits"]).Count(h=>(string)h["Source"]==id&&(int)h["HpLoss"]>0);Assert.AreEqual(Math.Min(100,hits*4),(int)row["charge"],id);}Assert.Greater(((JArray)hud["ultimates"]).Sum(r=>(int)r["charge"]),0);}
 [Test] public void AutoOffKeepsAcceptedCastAndDoesNotConsumeAgain(){var j=Quiet(false);j["operatorAutomation"]["charge"]["op_kyle"]=100;var s=Restore(j,false);Auto(s,true);s.Advance(500000,1);var cmd=((JArray)JObject.Parse(s.CaptureLocalState())["commands"]).Single();string id=(string)cmd["id"];Assert.AreEqual("CASTING",s.CommandStatus(id));Auto(s,false);Assert.AreEqual("CASTING",s.CommandStatus(id));s.Advance(10000000,20);Assert.AreEqual("APPLIED",s.CommandStatus(id));Assert.AreEqual(1,((JArray)JObject.Parse(s.CaptureLocalState())["commands"]).Count);}
 [Test] public void FullChargeWithoutAvailableTargetDoesNotGlowOrSpam(){var j=Quiet(false);foreach(var actor in (JArray)j["actors"])if(((string)actor["id"]).StartsWith("wave."))actor["availableAt"]=10000;j["operatorAutomation"]["charge"]["op_reina"]=100;var s=Restore(j,false);Auto(s,true);s.Advance(5000000,10);var row=((JArray)s.ReadHudState()["ultimates"]).Single(r=>(string)r["actor"]=="op_reina");Assert.AreEqual(100,(int)row["charge"]);Assert.IsFalse((bool)row["enabled"]);Assert.AreEqual(0,((JArray)JObject.Parse(s.CaptureLocalState())["commands"]).Count);}

 [Test] public void DirectAdapterRejectsV1CommandsInsideV3EvenWithFreshDigest(){const string root="D:/Project/LASTRAIL/unity-project/QA/Unity1Artifacts/Fixtures/";var p=JObject.Parse(File.ReadAllText(root+"ce03-general-active-auto-hM29XX/prepared.json"));var old=JObject.Parse(File.ReadAllText(root+"ce03-frontline-policy-UtU7yJ/prepared.json"));p["commandContract"]=old["commandContract"].DeepClone();var fields=new JObject();foreach(string k in new[]{"ownedSelection","carriageOwnership","draft","commandContract"})fields[k]=p[k].DeepClone();p["prepareSha256"]=Ce03CommandContract.Sha(Ce03CommandContract.Canonical(fields));Assert.Throws<FormatException>(()=>BasicCombatSimulation.FromPreparedProfileForLocalTest(p,(JObject)p["ownedSelection"],(string)p["ownedSelection"]["accountId"],1));}

}
